INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-10', 10, '第10課 听力训练', 'listening/listening-lesson-10.mp3', 194862, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn10-s1', 'listen-10', 1, 'text', '听录音，根据录音中的内容仿照例子写下相应的数字。', 9720, 100036, '今、9時40分です。', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s1-q1', 'lsn10-s1', 1, '明日の映画は＿＿時＿＿分からです。', '[]'::jsonb, '4時30分|4時半|4時30分から|4時半から');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s1-q2', 'lsn10-s1', 2, '会議は＿＿時＿＿分までです。', '[]'::jsonb, '5時25分|5時25分まで');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s1-q3', 'lsn10-s1', 3, '水曜日の授業は＿＿時＿＿分までです。', '[]'::jsonb, '3時30分|3時半|3時30分まで|3時半まで');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s1-q4', 'lsn10-s1', 4, 'お茶の約束は明日の＿＿時＿＿分です。', '[]'::jsonb, '2時30分|2時半');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l1', 'lsn10-s1', 1, 'A', 10020, 17194, 'すみません、今何時ですか。', 'A：请问现在几点？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l2', 'lsn10-s1', 2, 'B', 18160, 21154, '9時40分です。', 'B：9点40分。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l3', 'lsn10-s1', 3, 'A', 26286, 33191, '明日の映画は何時からですか。', 'A：明天的电影几点开始？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l4', 'lsn10-s1', 4, 'B', 33883, 36596, '4時半からです。', 'B：4点半开始。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l5', 'lsn10-s1', 5, 'A', 41720, 48185, '今日の会議は５時までですか。', 'A：今天的会议到5点吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l6', 'lsn10-s1', 6, 'B', 50027, 53755, 'いいえ、５時25分までですよ。', 'B：不，到5点25分。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l7', 'lsn10-s1', 7, 'A', 58886, 66115, '大学の授業は何時までですか。', 'A：大学的课到几点？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l8', 'lsn10-s1', 8, 'B', 66915, 69673, '水曜日は午後3時半までです。', 'B：周三到下午3点半。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l9', 'lsn10-s1', 9, 'B', 70560, 76069, '金曜日は夜7時50分までです。', 'B：周五到晚上7点50分。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l10', 'lsn10-s1', 10, 'A', 81186, 88700, '明日、いっしょにお茶をしましょうか。', 'A：明天一起喝茶吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l11', 'lsn10-s1', 11, 'B', 88701, 92660, 'いいですね。午後とかはどうですか。', 'B：好啊。下午怎么样？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l12', 'lsn10-s1', 12, 'A', 94335, 96105, 'はい、2時半は大丈夫ですか。', 'A：好，2点半可以吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s1-l13', 'lsn10-s1', 13, 'B', 96990, 99336, 'いいですよ。そうしましょう。', 'B：可以。就这么定了。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn10-s2', 'listen-10', 2, 'tf', '听录音，女生同意男生的提议时画（○），不同意时画（×）。', 118147, 186427, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s2-q1', 'lsn10-s2', 1, '明日、いっしょにテニスをしましょう。', '[]'::jsonb, '○');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s2-q2', 'lsn10-s2', 2, '暑いので、コーラを飲みましょう。', '[]'::jsonb, '×');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s2-q3', 'lsn10-s2', 3, '明日、会議があります。', '[]'::jsonb, '○');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn10-s2-q4', 'lsn10-s2', 4, '明日、いっしょに食事をしましょう。', '[]'::jsonb, '×');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l1', 'lsn10-s2', 1, 'A', 118447, 125731, '明日、いっしょにテニスをしましょうか。', 'A：明天一起打网球吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l2', 'lsn10-s2', 2, 'B', 126840, 132663, 'いいですね。そうしましょう。', 'B：好啊。就这么办。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l3', 'lsn10-s2', 3, 'A', 136572, 140351, '暑いですね。', 'A：真热啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l4', 'lsn10-s2', 4, 'B', 140704, 145512, 'あ、冷蔵庫にコーラがありますよ。どうぞ。', 'B：啊，冰箱里有可乐，请喝。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l5', 'lsn10-s2', 5, 'A', 147143, 152996, 'あ、大丈夫です。ありがとう。', 'A：啊，不用了。谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l6', 'lsn10-s2', 6, 'A', 157026, 161135, '明日、会議ありますね？', 'A：明天有会议吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l7', 'lsn10-s2', 7, 'B', 161442, 161982, 'ありますよ。午後は？', 'B：有啊。下午呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l8', 'lsn10-s2', 8, 'A', 161983, 166093, 'うん、午後は大丈夫ですよ。', 'A：嗯，下午可以。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l9', 'lsn10-s2', 9, 'A', 171220, 176130, '明日、いっしょに食事をしましょうか。', 'A：明天一起吃饭吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l10', 'lsn10-s2', 10, 'B', 176410, 179902, '明日はちょっと…。', 'B：明天有点……');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l11', 'lsn10-s2', 11, 'A', 180081, 183659, 'そうですか。', 'A：这样啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn10-s2-l12', 'lsn10-s2', 12, 'B', 183896, 185727, 'あ、今度はぜひいっしょに。', 'B：啊，下次一定一起。');
